import { Component } from '@angular/core'; // import komponentu

@Component({
  selector: 'app-privacy', // nazwa selektora komponentu
  standalone: true, // komponent standalone
  imports: [], // importowane moduły/komponenty
  templateUrl: '../privacy/privacy.component.html', // ścieżka do szablonu HTML
  styleUrls: ['./privacy.component.css'] // poprawnie: tablica plików CSS
})
export class PrivacyComponent { // definicja klasy komponentu

}
